13	/// ## What it does
14	/// Checks for unnecessary key checks prior to accessing a dictionary.
15	///
16	/// ## Why is this bad?
17	/// When working with dictionaries, the `get` can be used to access a value
18	/// without having to check if the dictionary contains the relevant key,
19	/// returning `None` if the key is not present.
20	///
21	/// ## Example
22	/// ```python
23	/// if "key" in dct and dct["key"]:
24	///     ...
25	/// ```
26	///
27	/// Use instead:
28	/// ```python
29	/// if dct.get("key"):
30	///     ...
31	/// ```
32	///
33	/// ## Fix safety
34	/// This rule's fix is marked as safe, unless the expression contains comments.
35	#[derive(ViolationMetadata)]
36	#[violation_metadata(stable_since = "v0.2.0")]
37	pub(crate) struct UnnecessaryKeyCheck;
38	
39	impl AlwaysFixableViolation for UnnecessaryKeyCheck {
40	    #[derive_message_formats]
41	    fn message(&self) -> String {
42	        "Unnecessary key check before dictionary access".to_string()
43	    }
44	
45	    fn fix_title(&self) -> String {
46	        "Replace with `dict.get`".to_string()
47	    }
48	}
49	
50	/// RUF019
51	pub(crate) fn unnecessary_key_check(checker: &Checker, expr: &Expr) {
52	    if !checker.semantic().in_boolean_test() {
53	        return;
54	    }
55	
56	    let Expr::BoolOp(ast::ExprBoolOp {
57	        op: BoolOp::And,
58	        values,
59	        ..
60	    }) = expr
61	    else {
62	        return;
63	    };
64	
65	    let [left, right] = values.as_slice() else {
66	        return;
67	    };
68	
69	    // Left should be, e.g., `key in dct`.
70	    let Expr::Compare(ast::ExprCompare {
71	        left: key_left,
72	        ops,
73	        comparators,
74	        ..
75	    }) = left
76	    else {
77	        return;
78	    };
79	
80	    if !matches!(&**ops, [CmpOp::In]) {
81	        return;
82	    }
83	
84	    let [obj_left] = &**comparators else {
85	        return;
86	    };
87	
88	    // Right should be, e.g., `dct[key]`.
89	    let Expr::Subscript(ast::ExprSubscript {
90	        value: obj_right,
91	        slice: key_right,
92	        ..
93	    }) = right
94	    else {
95	        return;
96	    };
97	
98	    if ComparableExpr::from(obj_left) != ComparableExpr::from(obj_right)
99	        || ComparableExpr::from(key_left) != ComparableExpr::from(key_right)
100	    {
101	        return;
102	    }
103	
104	    if contains_effect(obj_left, |id| checker.semantic().has_builtin_binding(id))
105	        || contains_effect(key_left, |id| checker.semantic().has_builtin_binding(id))
106	    {
107	        return;
108	    }
109	
110	    let mut diagnostic = checker.report_diagnostic(UnnecessaryKeyCheck, expr.range());
111	
112	    let applicability = if checker.comment_ranges().intersects(expr.range()) {
113	        Applicability::Unsafe
114	    } else {
115	        Applicability::Safe
116	    };
117	
118	    diagnostic.set_fix(Fix::applicable_edit(
119	        Edit::range_replacement(
120	            format!(
121	                "{}.get({})",
122	                checker.locator().slice(
123	                    parenthesized_range(obj_right.into(), right.into(), checker.tokens(),)
124	                        .unwrap_or(obj_right.range())
125	                ),
126	                checker.locator().slice(
127	                    parenthesized_range(key_right.into(), right.into(), checker.tokens(),)
128	                        .unwrap_or(key_right.range())
129	                ),
130	            ),
131	            expr.range(),
132	        ),
133	        applicability,
134	    ));
135	}
