/// A tristate classification of whether an expression has side effects.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum SideEffect {
    /// The expression is definitely free of side effects.
    Absent,
    /// The expression may have side effects. For example, an f-string
    /// interpolation may invoke `__format__` or `__str__`.
    Possible,
    /// The expression is assumed to have side effects. For example, a named
    /// expression (walrus operator) or a function call.
    Present,
}

impl SideEffect {
    /// Return `true` if the expression is assumed to have side effects.
    pub const fn is_present(self) -> bool {
        matches!(self, SideEffect::Present)
